38	void ConfigModeScreen::render_audio_page(const worker_map_t& workers, const handler_map_t& handlers) {
39	  auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
40	  auto sound_manager = workers.worker<SoundManager>(k_worker_sound_manager);
41	
42	  uint8_t volume = settings->get_audio_volume();
43	  bool clicks_on = sound_manager && sound_manager->isSoundEnabled();
44	  bool alarm_on = settings->get_error_alert_sound();
45	
46	  drawButton1("Next");
47	  drawButton2(_audio_field == e_audio_field_volume ? "+5%\nHold:+20%" : "Toggle");
48	  drawButton3("Back");
49	
50	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
51	  M5.Lcd.setCursor(0, 45, &fonts::Font2);
52	  M5.Lcd.printf("Audio Settings\n\n");
53	
54	  const uint16_t hl_fg = LCD_COLOR_BACKGROUND;
55	  const uint16_t hl_bg = LCD_COLOR_DEFAULT;
56	  const uint16_t fg = LCD_COLOR_DEFAULT;
57	  const uint16_t bg = LCD_COLOR_BACKGROUND;
58	
59	  M5.Lcd.setTextColor(_audio_field == e_audio_field_volume ? hl_fg : fg,
60	                      _audio_field == e_audio_field_volume ? hl_bg : bg);
61	  M5.Lcd.printf(" Volume:  %3u%%       \n", volume);
62	  M5.Lcd.setTextColor(fg, bg);
63	  M5.Lcd.printf("\n");
64	
65	  M5.Lcd.setTextColor(_audio_field == e_audio_field_clicks ? hl_fg : fg,
66	                      _audio_field == e_audio_field_clicks ? hl_bg : bg);
67	  M5.Lcd.printf(" Clicks:  %s      \n", clicks_on ? "ON " : "OFF");
68	  M5.Lcd.setTextColor(fg, bg);
69	  M5.Lcd.printf("\n");
70	
71	  M5.Lcd.setTextColor(_audio_field == e_audio_field_alarm ? hl_fg : fg,
72	                      _audio_field == e_audio_field_alarm ? hl_bg : bg);
73	  M5.Lcd.printf(" Alarm:   %s      \n", alarm_on ? "ON " : "OFF");
74	  M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, bg);
75	  M5.Lcd.printf("\nA: select  B: change\n");
76	  M5.Lcd.printf("Volume wraps 100->0\n");
77	}
78	
79	void ConfigModeScreen::render_dim_brightness_page(const worker_map_t& workers, const handler_map_t& handlers) {
80	  auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
81	  uint8_t current = settings->get_dim_brightness();
82	
83	  // Draw button indicators at bottom of screen
84	  drawButton1("-5%\nHold:-20%");
85	  drawButton2("+5%\nHold:+20%");
86	  drawButton3("Back");
87	
88	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
89	  M5.Lcd.setCursor(0, 50, &fonts::Font2);
90	  M5.Lcd.printf("Dim Brightness\n\n");
91	  M5.Lcd.printf("Current: %u%%\n\n", current);
92	  M5.Lcd.printf("Controls the screen brightness used\n");
93	  M5.Lcd.printf("when the device is DIM or the\n");
94	  M5.Lcd.printf("animated screensaver is active.\n\n");
95	  M5.Lcd.setTextColor(LCD_COLOR_STALE_INCOMPLETE, LCD_COLOR_BACKGROUND);
96	  M5.Lcd.printf("Range: 0-100%%\n");
97	}
