99	BaseScreen* ConfigModeScreen::handle_input(Controller& controller, const worker_map_t& workers) {
100	  if (menu_open()) {
101	    auto* new_screen = handle_menu_input(controller, workers, CONFIG_MODE_MENU, e_config_MENU_MAX);
102	    if (new_screen) {
103	      return new_screen;
104	    }
105	    // Handle menu selection
106	    if (_current_page == e_config_page_reset_dose) {
107	      auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
108	      settings->reset_dose_rate();
109	      
110	      // Clear screen and show restart message
111	      M5.Lcd.clear(LCD_COLOR_BACKGROUND);
112	      M5.Lcd.setRotation(3);
113	      M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
114	      M5.Lcd.setCursor(46, 78, &fonts::Font4);  // Centered horizontally (320 - text width) / 2
115	      M5.Lcd.printf("DOSE RATE RESET\n");
116	      M5.Lcd.setCursor(100, 120, &fonts::Font2);
117	      M5.Lcd.printf("Restarting device...\n");
118	      
119	      delay(2000); // Wait 2 seconds
120	      DeviceUtils::shutdown(true); // Restart the device
121	    }
122	    else if (_current_page == e_config_page_back_to_main) {
123	      return &MenuWindow_i;
124	    }
125	  }
126	  else {
127	    auto button1 = workers.worker<ZenButton>(k_worker_button_1);
128	    auto button2 = workers.worker<ZenButton>(k_worker_button_2);
129	    auto button3 = workers.worker<ZenButton>(k_worker_button_3);
130	    if (button1->is_fresh() && button1->get_data().shortPress) {
131	      // Check if we're on the CPM threshold page for decrement functionality
132	      if (_current_page == e_config_page_cpm_threshold) {
133	        auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
134	        uint16_t current_threshold = settings->get_alert_threshold();
135	        uint16_t decrement = button1->get_data().longPress ? 100 : 10;
136	        uint16_t new_threshold;
137	
138	        // Handle underflow protection
139	        if (current_threshold <= decrement || current_threshold - decrement < 10) {
140	          new_threshold = 10;  // Minimum threshold
141	        } else {
142	          new_threshold = current_threshold - decrement;
143	        }
144	
145	        if (new_threshold != current_threshold) {
146	          settings->set_alert_threshold(new_threshold, false);
147	
148	          // Save to SD card
149	          if (SDInterface::i().ready()) {
150	            SDInterface::i().write_safezen_file_from_settings(*settings, false);
151	          }
152	
153	          force_next_render();
154	          M5_LOGD("CPM threshold decreased to: %u", new_threshold);
155	        }
156	      }
157	      // Audio Settings page: button A cycles the selected field
158	      else if (_current_page == e_config_page_audio) {
159	        _audio_field = (_audio_field + 1) % e_audio_field_MAX;
160	        force_next_render();
161	      }
162	      // Check if we're on the dim brightness page for decrement functionality
163	      else if (_current_page == e_config_page_dim_brightness) {
164	        auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
165	        uint8_t current = settings->get_dim_brightness();
166	        uint8_t step = button1->get_data().longPress ? 20 : 5;
167	        uint8_t new_value = (current > step) ? (uint8_t)(current - step) : 0;
168	
169	        if (new_value != current) {
170	          settings->set_dim_brightness(new_value, false);
171	          if (SDInterface::i().ready()) {
172	            SDInterface::i().write_safezen_file_from_settings(*settings, false);
173	          }
174	          force_next_render();
175	          M5_LOGD("Dim brightness decreased to: %u%%", new_value);
176	        }
177	      }
178	      else {
179	        open_menu(true);
180	        M5.Lcd.clear(LCD_COLOR_BACKGROUND);  // Clear screen when opening menu
181	        force_next_render();
182	      }
183	    }
184	    if (button2->is_fresh() && button2->get_data().shortPress) {
185	      // screen specific action
186	      switch (_current_page) {
187	        case e_config_page_reset_all:
188	          M5.Lcd.clear(LCD_COLOR_BACKGROUND);
189	          M5.Lcd.setRotation(3);
190	          M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
191	          M5.Lcd.setCursor(30, 78, &fonts::Font4);
192	          M5.Lcd.printf("RESET IN PROGRESS\n");
193	          M5.Lcd.setCursor(5, 120, &fonts::Font2);
194	
195	          M5.Lcd.printf("Removing all log files, This can take a while...\n");
196	          controller.factory_reset();
197	          M5.Lcd.clear(LCD_COLOR_BACKGROUND);
198	          M5.Lcd.setRotation(3);
199	          M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
200	          M5.Lcd.setCursor(27, 78, &fonts::Font4);
201	          M5.Lcd.printf("DEVICE MEMORY AND\n");
202	          M5.Lcd.setCursor(27, 110, &fonts::Font4);
203	          M5.Lcd.printf("SD HAVE BEEN RESET\n");
204	          M5.Lcd.setCursor(70, 160, &fonts::Font2);
205	          M5.Lcd.printf("Please turn off the device...\n");
206	          delay(UINT32_MAX); // Sleep for a long time.
207	          break;
208	        case e_config_page_main:
209	          _main_page_info_section = (_main_page_info_section + 1) % e_config_section_MAX;
210	          force_next_render();
211	          break;
212	        case e_config_page_set_home_gps: {
213	          // Set current GPS location as home
214	          auto* gps = workers.worker<GpsConnector>(k_worker_gps_connector);
215	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
216	          
217	          if (gps && gps->active() && gps->get_data().location_valid) {
218	            double new_lat = gps->get_data().latitude;
219	            double new_lon = gps->get_data().longitude;
220	            
221	            // Save the new home location
222	            settings->set_fixed_latitude(new_lat, false);
223	            settings->set_fixed_longitude(new_lon, false);
224	            
225	            // Also update last known location for reference
226	            settings->set_last_latitude(new_lat, false);
227	            settings->set_last_longitude(new_lon, false);
228	            
229	            // Save to SD card
230	            if (SDInterface::i().ready()) {
231	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
232	            }
233	            
234	            set_status_message(F(" HOME GPS LOCATION SET! "));
235	            force_next_render();
236	            M5_LOGD("Home GPS location set to: Lat %.6f, Lon %.6f", new_lat, new_lon);
237	          } else {
238	            set_status_message(F(" NO VALID GPS FIX! "));
239	            M5_LOGD("Cannot set home GPS - no valid fix");
240	          }
241	          break;
242	        }
243	        case e_config_page_cpm_threshold: {
244	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
245	          uint16_t current_threshold = settings->get_alert_threshold();
246	          uint16_t increment = button2->get_data().longPress ? 100 : 10;
247	          uint16_t new_threshold = current_threshold + increment;
248	          
249	          // Clamp to reasonable range
250	          if (new_threshold > 9999) {
251	            new_threshold = 9999;
252	          }
253	          if (new_threshold < 10) {
254	            new_threshold = 10;
255	          }
256	          
257	          if (new_threshold != current_threshold) {
258	            settings->set_alert_threshold(new_threshold, false);
259	            
260	            // Save to SD card
261	            if (SDInterface::i().ready()) {
262	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
263	            }
264	            
265	            force_next_render();
266	            M5_LOGD("CPM threshold updated to: %u", new_threshold);
267	          }
268	          break;
269	        }
270	        case e_config_page_dim_brightness: {
271	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
272	          uint8_t current = settings->get_dim_brightness();
273	          uint8_t step = button2->get_data().longPress ? 20 : 5;
274	          uint16_t temp = current + step; // use wider type to avoid overflow before clamp
275	          uint8_t new_value = (temp > 100) ? 100 : (uint8_t)temp;
276	
277	          if (new_value != current) {
278	            settings->set_dim_brightness(new_value, false);
279	            if (SDInterface::i().ready()) {
280	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
281	            }
282	            force_next_render();
283	            M5_LOGD("Dim brightness increased to: %u%%", new_value);
284	          }
285	          break;
286	        }
287	        case e_config_page_audio: {
288	          auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
289	          if (_audio_field == e_audio_field_volume) {
290	            uint8_t current = settings->get_audio_volume();
291	            uint8_t step = button2->get_data().longPress ? 20 : 5;
292	            uint16_t next = (uint16_t)current + step;
293	            uint8_t new_value = (next > 100) ? 0 : (uint8_t)next; // wrap-around
294	            settings->set_audio_volume(new_value, false);
295	            if (SDInterface::i().ready()) {
296	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
297	            }
298	            force_next_render();
299	            M5_LOGD("Audio volume set to: %u%%", new_value);
300	          }
301	          else if (_audio_field == e_audio_field_clicks) {
302	            auto sound_manager = workers.worker<SoundManager>(k_worker_sound_manager);
303	            if (sound_manager) {
304	              bool new_state = sound_manager->toggleSound();
305	              if (SDInterface::i().ready()) {
306	                SDInterface::i().write_safezen_file_from_settings(*settings, false);
307	              }
308	              force_next_render();
309	              M5_LOGD("Click sound toggled to: %s", new_state ? "ENABLED" : "DISABLED");
310	            }
311	          }
312	          else if (_audio_field == e_audio_field_alarm) {
313	            bool new_setting = !settings->get_error_alert_sound();
314	            settings->set_error_alert_sound(new_setting, false);
315	            if (SDInterface::i().ready()) {
316	              SDInterface::i().write_safezen_file_from_settings(*settings, false);
317	            }
318	            force_next_render();
319	            M5_LOGD("Alarm (error alert) sound toggled to: %s", new_setting ? "ENABLED" : "DISABLED");
320	          }
321	          break;
322	        }
323	        default:
324	          break;
325	      }
326	    }
327	    if (button3->is_fresh() && button3->get_data().shortPress) {
328	      // Handle page-specific back navigation
329	      switch (_current_page) {
330	        case e_config_page_cpm_threshold:
331	        case e_config_page_audio:
332	        case e_config_page_dim_brightness:
333	        case e_config_page_set_home_gps:
334	          // Go back to config menu, not main menu
335	          _current_page = e_config_page_main;
336	          M5.Lcd.clear(LCD_COLOR_BACKGROUND);  // Clear screen to avoid visual artifacts
337	          open_menu(false);
338	          force_next_render();
339	          return nullptr;  // Stay on config screen
340	        default:
341	          // For other pages, go back to main menu
342	          return &MenuWindow_i;
343	      }
344	    }
345	  }
346	
347	  return nullptr;
348	}
349	
350	void ConfigModeScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
351	  if (menu_open()) {
352	    if (!force) {
353	      return;
354	    }
355	    render_menu(CONFIG_MODE_MENU, e_config_MENU_MAX, true, 1);
356	  }
357	  else {
358	    if (!force) {
359	      return;
360	    }
361	    clear_screen_content();
362	
363	    switch (_current_page) {
364	      case e_config_page_main:
365	        render_page_main(workers, handlers);
366	        break;
367	      case e_config_page_ap:
368	        render_page_ap(workers, handlers);
369	        break;
370	      case e_config_page_wifi:
371	        render_page_wifi(workers, handlers);
372	        break;
373	      case e_config_page_sd_wipe:
374	        render_sd_wipe(workers, handlers);
375	        break;
376	      case e_config_page_cpm_threshold:
377	        render_cpm_threshold_page(workers, handlers);
378	        break;
379	      case e_config_page_audio:
380	        render_audio_page(workers, handlers);
381	        break;
382	      case e_config_page_dim_brightness:
383	        render_dim_brightness_page(workers, handlers);
384	        break;
385	      case e_config_page_set_home_gps:
386	        render_set_home_gps_page(workers, handlers);
387	        break;
388	      case e_config_page_reset_all:
389	        render_reset_device_sd(workers, handlers);
390	        break;
391	      default:
392	        break;
393	    }
394	  }
395	}
