573	void ConfigModeScreen::enter_screen(Controller& controller) {
574	  // Ensure low power mode is disabled so that WiFi/AP will start reliably
575	  PowerManager::exitLowPowerMode();
576	
577	  // If entering the Settings screen from outside and we're on the main page,
578	  // force the menu to open at the main entry
579	  if (_current_page == e_config_page_main) {
580	    _menu_index = e_config_page_main;
581	    open_menu(true);
582	    return;
583	  }
584	
585	  // For other pages, perform page-specific actions when the page is entered
586	  switch (_current_page) {
587	    case e_config_page_ap:
588	      WiFiWrapper_i.start_ap_server(controller.get_settings().get_device_id(), controller.get_settings().get_ap_password());
589	      controller.set_worker_active(k_worker_config_server, true);
590	      break;
591	    case e_config_page_wifi:
592	      WiFiWrapper_i.connect_wifi(controller.get_settings().get_wifi_ssid(), controller.get_settings().get_wifi_password());
593	      controller.set_worker_active(k_worker_config_server, true);
594	      break;
595	    case e_config_page_load_sd_config:
596	      if (controller.load_sd_config()) {
597	        set_status_message(F(" SD CONFIG LOADED, settings have been updated! "));
598	      }
599	      else {
600	        set_status_message(F(" LOAD CONFIG FAILED, no config or SD-card! "));
601	      }
602	      _current_page = e_config_page_main; // Back on main page
603	      open_menu(true);       // Re-enter menu
604	      break;
605	    case e_config_page_save_config_to_sd:
606	      if (controller.write_sd_config()) {
607	        set_status_message(F(" CONFIG SAVED, settings have been saved to SD! "));
608	      }
609	      else {
610	        set_status_message(F(" WRITE CONFIG FAILED, no SD-card! "));
611	      }
612	      _current_page = e_config_page_main; // Back on main page
613	      open_menu(true);       // Re-enter menu
614	      break;
615	    default:
616	      break;
617	  }
618	}
619	
620	void ConfigModeScreen::leave_screen(Controller& controller) {
621	  switch (_current_page) {
622	    case e_config_page_ap:
623	      WiFiWrapper_i.stop_ap_server();
624	      controller.set_worker_active(k_worker_config_server, false);
625	      break;
626	    case e_config_page_wifi:
627	      WiFiWrapper_i.disconnect_wifi();
628	      controller.set_worker_active(k_worker_config_server, false);
629	      break;
630	    default:
631	      break;
632	  }
633	
634	  // Set page to main in case we left through main menu
635	  _current_page = e_config_page_main;
636	  _main_page_info_section = e_config_section_device;
637	}
