32	void BaseScreen::drawButton(uint16_t x, const char* text, ButtonState state) {
33	  if (strlen(text) > BUTTON_TEXT_MAX_LENGTH) {
34	    // Don't render long button text :(
35	    return;
36	  }
37	
38	  int border_color = LCD_COLOR_BACKGROUND;
39	  int text_color = LCD_COLOR_STALE_INCOMPLETE;
40	
41	  if (strlen(text)) {
42	    switch (state) {
43	      case e_button_default:
44	        border_color = LCD_COLOR_DEFAULT;
45	        break;
46	      case e_button_active:
47	        border_color = LCD_COLOR_STALE_INCOMPLETE;
48	        break;
49	      case e_button_disabled:
50	        border_color = LCD_COLOR_INACTIVE;
51	        text_color = LCD_COLOR_INACTIVE;
52	        break;
53	    }
54	  }
55	
56	  M5.Lcd.drawRoundRect(x, -5, 90, 20, 4, border_color);
57	  M5.Lcd.setTextColor(text_color, LCD_COLOR_BACKGROUND);
58	
59	  // Center the button text, making sure around the text is whitespace to clear previous texts
60	  char blob[BUTTON_TEXT_MAX_LENGTH + 1] = "              ";
61	  for (size_t i = 0; i < strlen(text); ++i) {
62	    blob[i + ((BUTTON_TEXT_MAX_LENGTH - strlen(text)) / 2)] = text[i];
63	  }
64	  if (strlen(text) % 2 != BUTTON_TEXT_MAX_LENGTH % 2) {
65	    blob[BUTTON_TEXT_MAX_LENGTH - 1] = '\0';
66	  }
67	  M5.Lcd.drawString(blob, (x + 45) - static_cast<uint16_t>(strlen(blob) * 3), 10, &fonts::Font0);
68	  M5.Lcd.flush();
69	}
70	
71	void BaseScreen::drawButton1(const char* text, ButtonState state) const {
72	  drawButton(10, text, state);
73	}
74	
75	void BaseScreen::drawButton2(const char* text, ButtonState state) const {
76	  drawButton(115, text, state);
77	}
78	
79	void BaseScreen::drawButton3(const char* text, ButtonState state) const {
80	  drawButton(220, text, state);
81	}
