83	size_t BaseScreen::printFloatFont(float val, int prec, int x, int y, const lgfx::IFont* font) {
84	  char sz[32] = "";
85	  char format[32] = "";
86	  sprintf(format, "%%.%df", prec);
87	  sprintf(sz, format, val);
88	  return M5.Lcd.drawString((sz), x, y, font);
89	}
90	
91	// Prints int with fonts
92	size_t BaseScreen::printIntFont(unsigned long val, int x, int y, const lgfx::IFont* font) {
93	  char sz[32] = "";
94	  sprintf(sz, "%lu", val);  // Use %lu for unsigned long instead of %ld
95	  return M5.Lcd.drawString((sz), x, y, font);
96	}
97	
98	void BaseScreen::enter_screen(Controller& controller) {
99	}
100	
101	void BaseScreen::leave_screen(Controller& controller) {
102	}
103	
104	const char* BaseScreen::get_title() const {
105	  return _title;
106	}
107	
108	bool BaseScreen::has_status_bar() const {
109	  return _status_bar;
110	}
111	
112	void BaseScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
113	}
114	
115	void BaseScreen::do_render(const worker_map_t& workers, const handler_map_t& handlers) {
116	  render(workers, handlers, _force_render);
117	  _force_render = false;
118	}
119	
120	void BaseScreen::force_next_render() {
121	  _force_render = true;
122	}
123	
124	const __FlashStringHelper* BaseScreen::get_error_message(const worker_map_t& workers, const handler_map_t& handlers) const {
125	  if (required_tube && millis() > 6000 && !workers.worker<GeigerCounter>(k_worker_gm_sensor)->active()) {
126	    return STATUS_ERROR_GEIGER;
127	  }
128	  if (required_gps && millis() > 15000 && !workers.worker<GpsConnector>(k_worker_gps_connector)->active()) {
129	    return STATUS_ERROR_GPS;
130	  }
131	  if (required_sd && !SDInterface::i().can_write_logs()) {
132	    return STATUS_ERROR_SD;
133	  }
134	  if (required_wifi && WiFiWrapper_i.status() == WL_NO_SSID_AVAIL) {
135	    return STATUS_ERROR_WIFI_NO_SSID_AVAIL;
136	  }
137	  if (required_wifi && WiFiWrapper_i.status() == WL_CONNECT_FAILED) {
138	    return STATUS_ERROR_WIFI_CONNECT_FAILED;
139	  }
140	  if (required_wifi && WiFiWrapper_i.status() == WL_CONNECTION_LOST) {
141	    return STATUS_ERROR_WIFI_CONNECTION_LOST;
142	  }
143	
144	  return nullptr;
145	}
146	
147	const __FlashStringHelper* BaseScreen::get_status_message(const worker_map_t& workers, const handler_map_t& handlers) {
148	  // First check for persistent CPM alert message
149	  auto* gm_sensor = workers.worker<GeigerCounter>(k_worker_gm_sensor);
150	  if (gm_sensor && gm_sensor->get_data().alert) {
151	    // CPM is above threshold - show persistent alert message
152	    return F(" ⚠ CPM ALERT ACTIVE ⚠ ");
153	  }
154	  
155	  // Check if temporary message exists and hasn't timed out
156	  if (_message) {
157	    unsigned long current_millis = millis();
158	    long time_elapsed = current_millis - _status_message_time;
159	    if (_status_message_time && (time_elapsed < STATUS_MESSAGE_DURATION)) {
160	      return _message;
161	    } else {
162	      _message = nullptr;
163	      _status_message_time = 0;
164	    }
165	  }
166	  return nullptr;
167	}
168	
169	void BaseScreen::set_status_message(const __FlashStringHelper* message) {
170	  _message = message;
171	  _status_message_time = millis();
172	}
173	
174	void BaseScreen::clear_screen_content() {
175	  M5.Lcd.fillRect(0, 20, 320, 180, LCD_COLOR_BACKGROUND);
176	}
177	
178	BaseScreen* BaseScreenWithMenu::handle_menu_input(Controller& controller, const worker_map_t& workers, const MenuItem items[], int menu_max) {
179	  auto button1 = workers.worker<ZenButton>(k_worker_button_1);
180	  auto button2 = workers.worker<ZenButton>(k_worker_button_2);
181	  auto button3 = workers.worker<ZenButton>(k_worker_button_3);
182	
183	  // Button 1 is move index down
184	  if (button1->is_fresh() && button1->get_data().shortPress) {
185	    ++_menu_index;
186	    _menu_index %= menu_max;
187	    force_next_render();
188	  }
189	
190	  // Button 2 move index up
191	  if (button2->is_fresh() && button2->get_data().shortPress) {
192	    _menu_index = _menu_index + menu_max - 1;
193	    _menu_index %= menu_max;
194	    force_next_render();
195	  }
196	
197	  // Button 3 change view
198	  if (button3->is_fresh() && button3->get_data().shortPress && items[_menu_index].enabled) {
199	    // Save the selected mode to LocalStorage
200	    auto* settings = workers.worker<LocalStorage>(k_worker_local_storage);
201	    if (items[_menu_index].screen == &SurveyModeScreen_i) {
202	      settings->set_last_mode(LocalStorage::e_operational_mode_survey, true);
203	    } else if (items[_menu_index].screen == &DriveModeScreen_i) {
204	      settings->set_last_mode(LocalStorage::e_operational_mode_drive, true);
205	    } else if (items[_menu_index].screen == &FlightModeScreen_i) {
206	      settings->set_last_mode(LocalStorage::e_operational_mode_flight, true);
207	    } else if (items[_menu_index].screen == &FixedModeScreen_i) {
208	      settings->set_last_mode(LocalStorage::e_operational_mode_fixed, true);
209	    } else if (items[_menu_index].screen == &SatelliteViewScreen_i) {
210	      settings->set_last_mode(LocalStorage::e_operational_mode_satellite, true);
211	    }
212	
213	    if (items[_menu_index].screen) {
214	      // Swap screens
215	      return items[_menu_index].screen;
216	    } else {
217	      // Swap pages internally
218	      _menu_open = false;
219	      // Don't clear the entire screen, just the content area to avoid flickering
220	      clear_screen_content();
221	      if (_menu_index != _current_page) {
222	        leave_screen(controller);
223	        _current_page = _menu_index;
224	        enter_screen(controller);
225	      }
226	      force_next_render();
227	    }
228	
229	  }
230	
231	  return nullptr;
232	}
233	
234	void BaseScreenWithMenu::render_menu(const MenuItem items[], int menu_max, bool outline, int outline_button) {
235	  // Draw buttons
236	  drawButton1("Down");
237	  drawButton2("Up");
238	  drawButton3("Enter", items[_menu_index].enabled ? e_button_active : e_button_disabled);
239	
240	  if (outline) {
241	    // Draw menu overlay border
242	    M5.Lcd.drawRoundRect(10, 20, 300, 170, 4, items[_menu_index].enabled ? LCD_COLOR_STALE_INCOMPLETE : LCD_COLOR_INACTIVE);
243	    if (outline_button == 3) {
244	      // Visually connect button to overlay
245	      M5.Lcd.fillRect(220, 12, 90, 12, LCD_COLOR_BACKGROUND);
246	      M5.Lcd.drawLine(220, 12, 220, 20, items[_menu_index].enabled ? LCD_COLOR_STALE_INCOMPLETE : LCD_COLOR_INACTIVE);
247	      M5.Lcd.drawLine(309, 12, 309, 23, items[_menu_index].enabled ? LCD_COLOR_STALE_INCOMPLETE : LCD_COLOR_INACTIVE);
248	    }
249	  }
250	
251	  // Clear menu area to prevent overlapping text
252	  M5.Lcd.fillRect(16, 26, 144, 158, LCD_COLOR_BACKGROUND);
253	  
254	  // Draw tooltip block
255	  M5.Lcd.fillRoundRect(161, 26, 142, 158, 4, LCD_COLOR_BACKGROUND);
256	  // Draw separate line between menu and tooltip
257	  M5.Lcd.drawLine(160, 33, 160, 177, LCD_COLOR_STALE_INCOMPLETE);
258	
259	  // Calculate visible range - show at most 9 items to fit on screen
260	  int startIdx = max(0, _menu_index - 4);
261	  int endIdx = min(menu_max, startIdx + 9);
262	  
263	  // Adjust startIdx if we have fewer than 9 items at the end
264	  if (endIdx - startIdx < 9 && startIdx > 0) {
265	    startIdx = max(0, endIdx - 9);
266	  }
267	  
268	  for (int i = startIdx; i < endIdx; ++i) {
269	    int yPos = 48 + ((i - startIdx) * 16); // Adjust y position based on visible range
270	    M5.Lcd.setTextColor(items[i].enabled ? (i == _menu_index ? LCD_COLOR_STALE_INCOMPLETE : LCD_COLOR_DEFAULT) : LCD_COLOR_INACTIVE, LCD_COLOR_BACKGROUND);
271	    M5.Lcd.drawLine(16, yPos, 159, yPos, (i == _menu_index ? (items[i].enabled ? LCD_COLOR_STALE_INCOMPLETE : LCD_COLOR_INACTIVE) : LCD_COLOR_BACKGROUND));
272	    M5.Lcd.setCursor(16, yPos + 8, &fonts::Font2);
273	    if (i == _menu_index) {
274	      M5.Lcd.print("> ");
275	    }
276	    else {
277	      M5.Lcd.print("  ");
278	    }
279	    M5.Lcd.print(items[i].title);
280	    M5.Lcd.print("  ");
281	  }
282	  
283	  // Show scroll indicators if needed
284	  if (startIdx > 0) {
