  if (!force) {
    return;
  }
  if (menu_open()) {
    render_menu(SD_MENU, e_sd_MENU_MAX, true, 1);
    return;
  }
  clear_screen_content();
  if (_current_page == e_sd_page_wipe) {
    render_sd_wipe(workers, handlers);
  }
