  if (!force) {
    return;
  }
  if (menu_open()) {
    render_menu(WIFI_MENU, e_wifi_MENU_MAX, true, 1);
    return;
  }
  clear_screen_content();
  if (_current_page == e_wifi_page_ap) {
    render_page_ap(workers, handlers);
  } else if (_current_page == e_wifi_page_local) {
    render_page_local(workers, handlers);
  }
}

